		<div class="elementor-element elementor-element-1ecb32d e-con-full e-flex e-con e-child" data-id="1ecb32d" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
				<div class="elementor-element elementor-element-d5f8d80 elementor-widget elementor-widget-text-editor" data-id="d5f8d80" data-element_type="widget" data-widget_type="text-editor.default">
